import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p49_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor max_reduce_dim1_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("max_reduce_dim1_cuda", &max_reduce_dim1_cuda, "max reduce dim=1 cuda");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cfloat>

__device__ __forceinline__ float warp_max(float val) {
    val = fmaxf(val, __shfl_down_sync(0xffffffff, val, 16));
    val = fmaxf(val, __shfl_down_sync(0xffffffff, val, 8));
    val = fmaxf(val, __shfl_down_sync(0xffffffff, val, 4));
    val = fmaxf(val, __shfl_down_sync(0xffffffff, val, 2));
    val = fmaxf(val, __shfl_down_sync(0xffffffff, val, 1));
    return val;
}

// Each warp handles one output column k for a given batch n.
// blockDim.x = 256, so columns_per_block = 8 warps per block.
// Grid: (ceil(K / columns_per_block), N)
template <int BLOCK_SIZE>
__global__ void max_reduce_dim1_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int M, int K
) {
    const int columns_per_block = BLOCK_SIZE / 32;
    const int warp_id = threadIdx.x / 32;
    const int lane    = threadIdx.x % 32;

    const int k = blockIdx.x * columns_per_block + warp_id;
    const int n = blockIdx.y;

    if (k >= K || n >= N) return;

    const float* row_base = input + (long long)n * M * K + k;

    float local_max = -FLT_MAX;
    for (int m = lane; m < M; m += 32) {
        float v = row_base[(long long)m * K];
        local_max = fmaxf(local_max, v);
    }

    local_max = warp_max(local_max);

    if (lane == 0) {
        output[(long long)n * K + k] = local_max;
    }
}

torch::Tensor max_reduce_dim1_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dim() == 3, "x must be 3D");

    const int N = x.size(0);
    const int M = x.size(1);
    const int K = x.size(2);

    auto output = torch::empty({N, K}, x.options());

    const int BLOCK_SIZE = 256;
    const int columns_per_block = BLOCK_SIZE / 32;
    dim3 grid((K + columns_per_block - 1) / columns_per_block, N);
    dim3 block(BLOCK_SIZE);

    max_reduce_dim1_kernel<BLOCK_SIZE><<<grid, block, 0, at::cuda::getDefaultCUDAStream()>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        N, M, K
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs Max reduction over a specific dimension.
        """
    def __init__(self, dim: int):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the model with the dimension to reduce over.

                Args:
                    dim (int): The dimension to reduce over.
                """
        self.dim = dim
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Applies Max reduction over the specified dimension to the input tensor.

                Args:
                    x (torch.Tensor): Input tensor.

                Returns:
                    torch.Tensor: Output tensor after Max reduction over the specified dimension.
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        if x.is_cuda and x.dtype == torch.float32 and x.dim() == 3 and self.dim == 1 and x.is_contiguous():
            return _stark_get_extension().max_reduce_dim1_cuda(x)
        return torch.max(x, dim=self.dim)[0]
        # <<<END_IMPROVE>>>

